 const localizedForm=(x:any,code:string):Form=>{const value=code==="en"?x:(x.translations?.[code]||{});return{id:x.id,kind:x.kind||"chapter",section:x.section||"General Muslim Life",parentCategorySlug:x.parentCategorySlug||"",order:x.order||1,title:value.title||"",icon:x.icon||"\uD83C\uDF3F",subtitle:value.subtitle||"",surah:value.quran?.surah||"",reference:value.quran?.reference||"",arabic:value.quran?.arabic||"",meaning:value.quran?.meaning||"",lesson:value.quran?.lesson||"",introduction:(value.introduction||[]).join("\n"),lessons:(value.lessons||[]).join("\n"),actions:(value.actions||[]).join("\n"),mistakes:(value.mistakes||[]).join("\n"),checklist:(value.checklist||[]).join("\n"),practice:value.practice||"",reflection:value.reflection||"",summary:value.summary||"",content:(value.introduction||[]).join("\n\n"),sources:(value.sources||[]).map((s:any)=>[s.label,s.note,s.url].join(" | ")).join("\n"),published:x.published!==false}};
 const selectLanguage=(code:string)=>{if(code!=="en"&&!form.id){setMessage("First save this item in English. Then choose another language.");return}setLanguage(code);if(form.id){const item=items.find(x=>x.id===form.id);if(item)setForm(localizedForm(item,code))}setMessage(code==="en"?"Editing the English base content.":itemLanguageMessage(code))};
 const itemLanguageMessage=(code:string)=>{const name=languages.find(x=>x.code===code)?.label||code.toUpperCase(),item=items.find(x=>x.id===form.id);return item?.translations?.[code]?`Editing saved ${name} translation.`:`Add the ${name} translation. Empty fields will fall back to English in the app.`};
