$panelAnchor = '<div className="panelHead"><div><small>{form.id?"EDIT LIFESTYLE CONTENT":form.kind==="category"?"LIFESTYLE CARD FORM":"NEW CHAPTER FORM"}</small><h2>{form.kind==="category"?"Create Lifestyle Card":"Create Chapter"}</h2></div><button disabled={saving}>{saving?"Saving...":"Save"}</button></div><div className="grid">'
$languagePanel = @'
<div className="panelHead"><div><small>{form.id?"EDIT LIFESTYLE CONTENT":form.kind==="category"?"LIFESTYLE CARD FORM":"NEW CHAPTER FORM"}</small><h2>{form.kind==="category"?"Create Lifestyle Card":"Create Chapter"}</h2></div><button disabled={saving}>{saving?"Saving...":"Save"}</button></div><section className="languageWorkspace"><div className="languageWorkspaceTop"><div><small>CONTENT LANGUAGE</small><h3>{languages.find(x=>x.code===language)?.label||language.toUpperCase()}</h3><p>{language==="en"?"English is the base content and fallback for every language.":form.id?(items.find(x=>x.id===form.id)?.translations?.[language]?"Saved translation - edit and save changes.":"Translation not added yet - enter localized content below."):"Save English first to unlock translations."}</p></div><div className={language==="en"?"languageStatus base":"languageStatus"}>{language==="en"?"BASE":items.find(x=>x.id===form.id)?.translations?.[language]?"COMPLETE":"MISSING"}</div></div><div className="languageControls"><input aria-label="Search languages" value={languageQuery} onChange={e=>setLanguageQuery(e.target.value)} placeholder="Search Bengali, Arabic, Spanish..."/><select aria-label="Content language" value={language} onChange={e=>selectLanguage(e.target.value)}><option value="en">English (Base)</option>{languages.filter(x=>x.code!=="en"&&(!languageQuery.trim()||(`${x.label} ${x.code}`).toLowerCase().includes(languageQuery.trim().toLowerCase()))).map(x=><option key={x.code} value={x.code}>{x.label} ({x.code.toUpperCase()}){form.id&&items.find(item=>item.id===form.id)?.translations?.[x.code]?" - Saved":""}</option>)}</select></div>{form.id&&<div className="translationProgress"><b>{1+Object.keys(items.find(x=>x.id===form.id)?.translations||{}).length}</b><span>languages completed for this item</span><div>{["en",...Object.keys(items.find(x=>x.id===form.id)?.translations||{})].slice(0,12).map(code=><i key={code}>{code.toUpperCase()}</i>)}</div></div>}</section><div className="grid">
'@
