$css = '*{box-sizing:border-box}.languageWorkspace{margin-bottom:18px;padding:16px;border:1px solid #cfe1d5;border-radius:16px;background:linear-gradient(135deg,#f1f9f3,#fff)}.languageWorkspaceTop{display:flex;gap:16px;align-items:flex-start}.languageWorkspaceTop>div:first-child{flex:1}.languageWorkspaceTop small{font-size:9px;letter-spacing:1.2px;font-weight:900;color:#a17e24}.languageWorkspaceTop h3{margin:5px 0 3px;font-size:20px}.languageWorkspaceTop p{margin:0;color:#6d7e75;font-size:11px;line-height:1.5}.languageStatus{padding:7px 10px;border-radius:999px;background:#fff0e9;color:#a14f39;font-size:9px;font-weight:900}.languageStatus.base{background:#e1f2e7;color:#087a4d}.languageControls{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:13px}.languageControls input,.languageControls select{background:#fff}.translationProgress{display:flex;align-items:center;gap:8px;margin-top:12px;padding-top:12px;border-top:1px solid #dce9df}.translationProgress>b{font-size:18px;color:#087a4d}.translationProgress>span{font-size:10px;color:#64776d}.translationProgress>div{display:flex;gap:4px;margin-left:auto;flex-wrap:wrap;justify-content:flex-end}.translationProgress i{padding:4px 6px;border-radius:6px;background:#e4f3e8;color:#087a4d;font-size:8px;font-style:normal;font-weight:900}@media(max-width:650px){.languageControls{grid-template-columns:1fr}.translationProgress{align-items:flex-start;flex-wrap:wrap}.translationProgress>div{width:100%;justify-content:flex-start}}.chapterLibrary'
